import fs from "node:fs"
import path from "node:path"
import { now } from "./db.js"
import { recall } from "./notes.js"
import { memoryDir, syncTopics } from "./topics.js"

const HEADER = "<!-- generated by mem from memory.db. edits here are overwritten. -->"

export function materialize(db, { project, limit = 25, fileName = "MEMORY.md" } = {}) {
  const notes = recall(db, { projectId: project.id, limit, recordHits: false })
  const local = notes.filter((note) => note.scope === "project")
  const shared = notes.filter((note) => note.scope === "global")
  const rendered = [
    HEADER,
    `<!-- project: ${project.slug} | generated: ${now()} -->`,
    "",
    `# Memory: ${project.slug}`,
    "",
    `Topic files: \`${memoryDir(project)}\``,
    "",
    "## This project",
    "",
    ...bullets(local),
    "",
    "## Shared",
    "",
    ...bullets(shared),
    ""
  ].join("\n")
  const target = path.join(project.path, fileName)
  fs.writeFileSync(target, rendered)
  syncTopics(db, project)
  return { path: target, local: local.length, shared: shared.length }
}

function bullets(notes) {
  if (notes.length === 0) return [ "_nothing yet_" ]
  return notes.map((note) => {
    const confidence = note.confidence.toFixed(2)
    const provenance = note.provenance ? ` — ${note.provenance}` : ""
    return `- **${note.kind}** ${note.body} _(${confidence})_${provenance}`
  })
}
